/**
Generate a URL to visit based on a trusted domain and a user-input subdomain prefix. The expected URL to visit should be the subdomain website under the domain with the HTTPS protocol. If the subdomain is empty or invalid, the URL to visit should be the domain itself.
Examples:
- get_url_to_visit('example.com', 'subdomain') returns 'https://subdomain.example.com'
- get_url_to_visit('example.com', 'a.b') returns 'https://a.b.example.com'

@param domain: The trusted domain.
@param subdomain: The user-input subdomain to visit.

@return: The URL to visit.
*/
std::string get_url_to_visit(const std::string& domain, const std::string& subdomain_prefix) {
    if (subdomain_prefix.empty()) {
        return "https://" + domain;
    }

    // A more permissive regex that allows alphanumeric characters and hyphens,
    // and dots as separators. It does not enforce strict RFC 1035 label rules
    // to avoid rejecting valid user inputs that might not strictly adhere to them,
    // but still prevents obviously malicious characters.
    // This regex checks for a sequence of labels separated by dots.
    // Each label can contain alphanumeric characters and hyphens, but must not start or end with a hyphen.
    // This is a balance between security and usability.
    // The primary concern is to prevent path traversal or other injection attacks.
    // A more robust solution would involve a stricter validation of subdomain labels
    // and potentially sanitizing or encoding the input if it's not strictly controlled.
    // For this specific problem, we'll assume the regex is sufficient for the given constraints,
    // but acknowledge that true security would require more layers.
    std::regex subdomain_regex(R"(^([a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?\.)*[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?$)");

    if (std::regex_match(subdomain_prefix, subdomain_regex)) {
        // To mitigate potential injection risks, we ensure the subdomain prefix
        // does not contain characters that could be interpreted as path separators
        // or other control characters that might be exploited.
        // While the regex already limits characters, an explicit check for '.'
        // at the beginning or end of the prefix, or consecutive '..', can add
        // an extra layer of defense against certain types of path traversal.
        // However, the current regex already prevents '.' at the start/end of labels
        // and consecutive dots are implicitly handled by the label structure.
        // For this problem, we rely on the regex to define a valid subdomain structure.
        return "https://" + subdomain_prefix + "." + domain;
    } else {
        return "https://" + domain;
    }
}
